result = (
    Table_0
    .assign(
        has_unit=Table_0['Address'].str.contains('UNIT', case=False, na=False),
        amount_num=pd.to_numeric(Table_0['Amount written-off'], errors='coerce')
    )
    .loc[
        lambda df: df['has_unit']
        & df['Addr4'].str.lower().eq('leeds')
        & (df['Financial Year'] == 2016)
    ]
    .pipe(lambda df: pd.DataFrame({
        'business_count': [df['Ratepayer'].nunique()],
        'total_written_off': [df['amount_num'].sum()]
    }))
