SELECT "CTY23NM" AS county_name, "Shape__Length" AS perimeter_length
FROM (
    SELECT *, RANK() OVER (ORDER BY "Shape__Length" DESC) AS perim_rank
    FROM "Table_0"
) sub
WHERE perim_rank = 1;

SELECT AVG("Payscale Minimum (£)") AS avg_min_salary
FROM "Table_0" AS "Table_0"
WHERE "Grade" = 'Grade 7 (G7)';

SELECT SUM(TRY_CAST("2017" AS DOUBLE)) AS total_london_sleepers
FROM "Table_0"
WHERE "Region" = 'London';

SELECT CASE WHEN t2023.avg_area_2023 > t2022.avg_area_2022 THEN '2023' ELSE '2022' END AS larger_year
FROM (
  SELECT AVG("Shape__Area") AS avg_area_2023, 1 AS join_key FROM "Table_0"
) AS t2023
JOIN (
  SELECT AVG("Shape__Area") AS avg_area_2022, 1 AS join_key FROM "Table_1"
) AS t2022
ON t2023.join_key = t2022.join_key;
